package hard;public class BestTimeToBuyAndSellStockWithCooldown{public static int maxProfit(int[]p){if(p.length<=1)return 0;int buy=-p[0],sell=0,cool=0;for(int i=1;i<p.length;i++){int nb=Math.max(buy,cool-p[i]),ns=Math.max(sell,buy+p[i]),nc=Math.max(cool,sell);buy=nb;sell=ns;cool=nc;}return sell;}public static void main(String[]args){System.out.println("Cooldown: "+maxProfit(new int[]{1,2,3,0,2}));}}
